/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] gray_out;
  TopModule dut(.clk(clk), .rst_n(rst_n), .gray_out(gray_out));

  always #5 clk = ~clk;

  function [3:0] gray2bin(input [3:0] g);
    begin
      gray2bin[3] = g[3];
      gray2bin[2] = g[2] "'^ gray2bin[3];
      gray2bin[1] = g[1] ''^ gray2bin[2];
      gray2bin[0] = g[0] ''^ gray2bin[1];
    end
  endfunction

  integer i;
  reg [3:0] prev_gray;
  reg [3:0] prev_bin;
  initial begin
    $display("time clk rst gray bin");
    $monitor("%4t  %0b   %0b   %b  %0d", $time, clk, rst_n, gray_out, gray2bin(gray_out));
    #2;
    rst_n = 0;
    #8;
    rst_n = 1;
    prev_gray = gray_out;
    prev_bin = gray2bin(gray_out);
    for (i = 0; i < 12; i = i + 1) begin
      @(posedge clk);
      if ((i % 2) == 0) begin
        if (gray_out !== prev_gray) begin
          $display("ERROR: gray changed on odd hold cycle at i=%0d", i);
          $finish_and_return(1);
        end
      end else begin
        if (gray2bin(gray_out) !== (prev_bin + 1) % 16) begin
          $display("ERROR: bin did not increment by 1 on update cycle at i=%0d", i);
          $finish_and_return(1);
        end
        if (''^({gray_out ''^ prev_gray}) === 1'"'bx || ((gray_out "'^ prev_gray) != 4'"'b0001 && (gray_out "'^ prev_gray) != 4'"'b0010 && (gray_out "'^ prev_gray) != 4'"'b0100 && (gray_out "'^ prev_gray) != 4'"'b1000)) begin
          "'$display("ERROR: not gray transition at i=%0d", i);
          $finish_and_return(1);
        end
      end
      prev_gray = gray_out;
      prev_bin = gray2bin(gray_out);
    end
    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

